fn main() {
    // ---- String literals are string slices ----
    let s1: &str = "Hello, world!";  // &str is a string slice

    // ---- Slicing Strings ----
    let s2 = String::from("Hello, world!");
    let slice1 = &s2[0..5];  // "Hello"
    let slice2 = &s2[7..12];  // "world"
    let slice3 = &s2[..5];  // "Hello"
    let slice4 = &s2[7..];  // "world!"
    let slice5 = &s2[..];  // "Hello, world!"

    println!("slice1: {}", slice1);
    println!("slice2: {}", slice2);
    println!("slice3: {}", slice3);
    println!("slice4: {}", slice4);
    println!("slice5: {}", slice5);

    // ---- Working with string slices in functions ----
    let s3 = String::from("Hello, world!");
    let word = first_word(&s3);
    println!("First word: {}", word);

    // ---- String slices are immutable ----
    // You cannot modify a string slice
    // To modify, use String

    // ---- Converting between String and &str ----
    let s4 = String::from("hello");
    let slice: &str = &s4;  // &String can be used as &str
    let s5: String = slice.to_string();  // &str to String
    let s6: String = String::from(slice);  // &str to String

    // ---- String slice with invalid UTF-8 ----
    // Slicing invalid UTF-8 is a runtime error!
    // Use char indices for UTF-8 strings
}

fn first_word(s: &str) -> &str {
    let bytes = s.as_bytes();
    for (i, &item) in bytes.iter().enumerate() {
        if item == b' ' {
            return &s[0..i];
        }
    }
    &s[..]
}

fn main2() {
    // ---- Slicing and indexing ----
    let s = String::from("hello");

    // You can't index strings directly
    // let c = s[0];  // ERROR!

    // You can use chars() to iterate
    for c in s.chars() {
        println!("char: {}", c);
    }

    // ---- Byte vs Char indices ----
    let s = String::from("Hello, 世界!");
    println!("Byte length: {}", s.len());
    println!("Char count: {}", s.chars().count());

    // ---- Slicing with char boundaries ----
    // This works: &s[0..5]  // "Hello" (valid char boundary)
    // This might panic: &s[6..9]  // If it cuts a multi-byte character
}

